import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("should quote 5 G for an empty item list (processing fee only)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });

      expect(result).toEqual({ results: [{ premium: 5 }] });
    });
    it("should quote 105 G for a single plain sword (100 G base + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 105 }] });
    });
    it("should quote 65 G for a single plain amulet (60 G base + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "amulet" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 65 }] });
    });
    it("should quote 85 G for a single plain staff (80 G base + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "staff" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 85 }] });
    });
    it("should quote 45 G for a single plain potion (40 G base + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "potion" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 45 }] });
    });
    it("should quote 165 G for a plain sword and a plain amulet (160 G base + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }, { type: "amulet" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 165 }] });
    });
  });

  describe("quote — components and blocks", () => {
    it("should charge 25 G base per component (2 runes → 50 G base)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 55 }] });
    });
    it("should charge 60 G base for a block of exactly 3 alike components (3 runes)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 65 }] });
    });
    it("should charge 100 G base for 4 runes (no block — block requires exactly 3)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 105 }] });
    });
    it("should charge 175 G base for 7 runes (no block — block requires exactly 3)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 180 }] });
    });
    it("should charge 75 G base for 2 runes and 1 moonstone (no block — different types)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 80 }] });
    });
    it("should charge 120 G base for 3 runes and 3 moonstones (two separate blocks)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "moonstone" },
              { type: "moonstone" },
              { type: "moonstone" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 125 }] });
    });
  });

  describe("quote — item-specific modifiers", () => {
    it("should add 50 % of the item's base premium for a cursed item", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword", cursed: true }] }],
      });

      expect(result).toEqual({ results: [{ premium: 155 }] });
    });
    it.todo("should add 30 % of the item's base premium for enchantment level 5");
    it.todo("should not add the high-enchantment surcharge for enchantment level 4");
    it.todo("should add both surcharges for a cursed item with enchantment level 5");
    it.todo("should apply the cursed surcharge only to the cursed item on a multi-item policy");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("should add 10 % of the policy base premium as first insurance surcharge");
    it.todo("should subtract 20 % of the policy base premium for a customer with 2 years");
    it.todo("should not apply the loyalty discount for a customer with 1 year");
    it.todo("should subtract 15 % of the policy base premium on each quote after the first");
    it.todo("should apply the first insurance surcharge on a follow-up contract as well");
  });

  describe("quote — rounding", () => {
    it.todo("should round the final premium up to a whole G");
    it.todo("should keep intermediate amounts as fractions and round only the final premium");
  });

  describe("quote — integration", () => {
    it.todo("should quote 165 G for a newcomer with a cursed steel sword of enchantment 3");
    it.todo("should quote 160 G for a 3-year customer's second contract with a cursed sword of enchantment 7");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("should pay 400 G for 500 G damage to a regular sword (deductible 100 G)");
    it.todo("should pay 100 G for 200 G damage to a rune (no enchantment or material clause)");
    it.todo("should apply the 100 G deductible once per damage entry (sword 500 G + amulet 300 G → 600 G)");
    it.todo("should treat two damage entries of the same item type as separate damages");
  });

  describe("claim — special clauses", () => {
    it.todo("should pay 400 G for 1000 G damage to a steel sword with enchantment 9 (50 % then deductible)");
    it.todo("should pay 700 G for 800 G damage to a dragon-material sword with enchantment 5 (full then deductible)");
    it.todo("should pay 400 G for 1000 G damage to a dragon-material sword with enchantment 9 (50 % rule wins)");
    it.todo("should pay 400 G for 1000 G damage to a dragon-material sword with exactly enchantment 8");
  });

  describe("claim — cap", () => {
    it.todo("should report the remaining cap as twice the insurance sum minus the payout");
    it.todo("should base the insurance sum on unmodified item values (sword + amulet → cap 3200 G)");
    it.todo("should base the insurance sum on unmodified item values when a block discount applies (sword + 3 runes → cap 3500 G)");
    it.todo("should not raise the cap for a cursed item (cursed sword → cap 2000 G)");
    it.todo("should reduce the payout to the remaining cap when the cap is exhausted across successive claims");
  });

  describe("claim — rounding", () => {
    it.todo("should round the final payout down to a whole G");
  });

  describe("errors", () => {
    it.todo("should reject a quote containing an item of unknown type");
    it.todo("should reject a claim whose damage references an item not in the policy");
    it.todo("should reject a claim whose damage references an unknown item type");
    it.todo("should reject a claim with more damages of a type than the policy insures");
    it.todo("should reject a claim with a negative damage amount");
  });

  describe("scenario processing", () => {
    it.todo("should return one result per step in the same order as the input steps");
    it.todo("should resolve a claim's policy field to the quote step at that zero-based index");
  });
});
export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const isBlock = (sameTypeItems: Item[]): boolean =>
  sameTypeItems.length === BLOCK_SIZE;

const basePremiumOfItem = (item: Item): number => BASE_PREMIUMS[item.type];

const sumOfItemPremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);

const groupByType = (items: Item[]): Item[][] =>
  Object.values(
    items.reduce<Record<string, Item[]>>((groups, item) => {
      groups[item.type] = [...(groups[item.type] ?? []), item];
      return groups;
    }, {}),
  );

const basePremiumOfGroup = (items: Item[]): number =>
  isBlock(items) ? BLOCK_PREMIUM : sumOfItemPremiums(items);

const policyBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);

const CURSED_SURCHARGE_RATE = 0.5;

const surchargeOfItem = (item: Item): number =>
  item.cursed ? basePremiumOfItem(item) * CURSED_SURCHARGE_RATE : 0;

const sumOfItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + surchargeOfItem(item), 0);

const quote = (items: Item[]): QuoteResult => ({
  premium:
    PROCESSING_FEE + policyBasePremium(items) + sumOfItemSurcharges(items),
});

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const firstStep = scenario.steps[0] as QuoteStep;
  return { results: [quote(firstStep.items)] };
};

